/* re.green — logotipo e ícones da marca como data URIs (texto).
   Use quando o projeto não tem os arquivos binários (Skip, Maestro, protótipos).
   Copie para src/regreen/brand-assets.ts e use em <img src={LOGO_VERDE} alt="re.green" />.
   Originais em alta resolução: Intranet re.green › Documentos Compartilhados ›
   Relações Institucionais › Comunicação e Marketing › LOGO (junto com o Brandbook). */

/** Logotipo verde — para fundo claro (sidebar, barra do topo, login). Largura mínima 96px. */
export const LOGO_VERDE = 'data:image/png;base64,'

/** Logotipo Solar (claro) — só para fundo Verde Mata ou foto escura. */
export const LOGO_SOLAR = 'data:image/png;base64,'

/** Os 7 ícones ilustrativos (estados vazios, boas-vindas; 48–64px). O traço é quase preto:
    para pintar na cor da marca, use como máscara CSS, por exemplo:
    <span style={{ width: 48, height: 48, background: 'var(--rg-mata)',
      WebkitMask: `url(${ICONES.tucano}) center/contain no-repeat`,
      mask: `url(${ICONES.tucano}) center/contain no-repeat` }} aria-hidden /> */
export const ICONES = {
  jequitiba: 'data:image/svg+xml;base64,',
  pau_brasil: 'data:image/svg+xml;base64,',
  sapopema: 'data:image/svg+xml;base64,',
  tucano: 'data:image/svg+xml;base64,',
  lupa: 'data:image/svg+xml;base64,',
  pasta: 'data:image/svg+xml;base64,',
  relogio: 'data:image/svg+xml;base64,',
} as const

export type IconeMarca = keyof typeof ICONES
